<script lang="ts">
	import { invalidateAll } from '$app/navigation';import { api } from '$lib/api';
	let {data}=$props();let busy=$state(false);let error=$state('');let notice=$state('');
	let record=$derived(data.record);const canEdit=$derived(data.user.role==='DOKTER'&&data.user.id===record.doctorId);const canObserve=$derived(data.user.role==='PERAWAT');
	async function send(path:string,payload:object){busy=true;error='';notice='';try{await api(path,{method:path.endsWith('/observations')?'POST':'PATCH',body:JSON.stringify(payload)});await invalidateAll();notice='Perubahan tersimpan.';}catch(e){error=e instanceof Error?e.message:'Perubahan gagal disimpan.';}finally{busy=false;}}
	async function update(event:SubmitEvent){event.preventDefault();const f=new FormData(event.currentTarget as HTMLFormElement);await send(`/medical-records/${record.id}`,{expectedVersion:record.version,complaint:f.get('complaint'),diagnosis:f.get('diagnosis'),treatment:f.get('treatment'),notes:f.get('notes'),recordDate:f.get('recordDate')});}
	async function observe(event:SubmitEvent){event.preventDefault();const f=new FormData(event.currentTarget as HTMLFormElement);const number=(key:string)=>{const value=String(f.get(key)??'').trim();return value===''?null:Number(value);};await send(`/medical-records/${record.id}/observations`,{symptoms:f.get('symptoms'),nursingNote:f.get('nursingNote'),observedAt:new Date().toISOString(),temperature:number('temperature'),systolic:number('systolic'),diastolic:number('diastolic'),pulse:number('pulse'),respiratoryRate:number('respiratoryRate'),spo2:number('spo2')});}
	function measurement(value:number|null,unit:string){return value===null||value===undefined?'—':`${value} ${unit}`;}
</script>
<svelte:head><title>{record.patientName} · Rekam Medis | InpaCare</title></svelte:head>
<div class="crumb"><a href="/medical-records" class="text-link">Rekam Medis</a><span> / {record.medicalRecordNo}</span></div>
<section class="page-heading"><div><h1 class="page-title">Rekam Medis · {record.patientName}</h1><p class="page-subtitle">{record.medicalRecordNo} · {new Date(record.recordDate+'T12:00:00').toLocaleDateString('id-ID')} · dr. {record.doctorName}</p></div><a href="/medical-records" class="button secondary">Kembali</a></section>
{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="success" role="status">{notice}</p>{/if}
<section class="panel record-panel"><div class="panel-header"><div><h2>Catatan dokter</h2><p class="muted">Terakhir diperbarui {new Date(record.updatedAt).toLocaleString('id-ID')} · versi {record.version}</p></div></div>{#if canEdit}<form class="form-grid" onsubmit={update}><label class="field">Tanggal<input type="date" name="recordDate" value={record.recordDate} required /></label><label class="field">Keluhan<textarea name="complaint" rows="3" required>{record.complaint}</textarea></label><label class="field">Diagnosis<textarea name="diagnosis" rows="3" required>{record.diagnosis}</textarea></label><label class="field">Tindakan<textarea name="treatment" rows="3" required>{record.treatment}</textarea></label><label class="field">Catatan medis<textarea name="notes" rows="3">{record.notes}</textarea></label><div class="form-actions"><button class="button primary" disabled={busy}>Simpan perubahan</button></div></form>{:else}<dl class="clinical-grid"><div><dt>Keluhan</dt><dd>{record.complaint}</dd></div><div><dt>Diagnosis</dt><dd>{record.diagnosis}</dd></div><div><dt>Tindakan</dt><dd>{record.treatment}</dd></div><div><dt>Catatan medis</dt><dd>{record.notes||'—'}</dd></div></dl>{/if}</section>
<section class="panel"><div class="panel-header"><div><h2>Observasi keperawatan</h2><p class="muted">Pengukuran disimpan sebagai catatan yang dikirim perawat.</p></div><span class="badge">{record.observations.length} observasi</span></div>{#if canObserve}<details class="observe-form"><summary class="button secondary small">＋ Tambah observasi</summary><form class="form-grid" onsubmit={observe}><label class="field">Gejala/kondisi<textarea name="symptoms" rows="2" required maxlength="3000"></textarea></label><label class="field">Catatan keperawatan<textarea name="nursingNote" rows="2" maxlength="3000"></textarea></label><div class="vitals-grid"><label class="field">Suhu (°C)<input name="temperature" type="number" min="0" max="100" step="0.1" /></label><label class="field">Sistolik<input name="systolic" type="number" min="0" step="1" /></label><label class="field">Diastolik<input name="diastolic" type="number" min="0" step="1" /></label><label class="field">Nadi (bpm)<input name="pulse" type="number" min="0" step="1" /></label><label class="field">Pernapasan (/menit)<input name="respiratoryRate" type="number" min="0" step="1" /></label><label class="field">Saturasi O₂ (%)<input name="spo2" type="number" min="0" max="100" step="0.01" /></label></div><div class="form-actions"><button class="button primary" disabled={busy}>Simpan observasi</button></div></form></details>{/if}
	<div class="observations">{#each record.observations as observation (observation.id)}<article class="observation"><div class="observation-heading"><div><strong>{observation.nurseName}</strong><span class="muted"> · {new Date(observation.observedAt).toLocaleString('id-ID')}</span></div></div><p><strong>Gejala/kondisi:</strong> {observation.symptoms}</p>{#if observation.nursingNote}<p><strong>Catatan:</strong> {observation.nursingNote}</p>{/if}<dl class="vitals-grid values"><div><dt>Suhu</dt><dd>{measurement(observation.temperature,'°C')}</dd></div><div><dt>Tekanan darah</dt><dd>{observation.bloodPressure??'—'}</dd></div><div><dt>Nadi</dt><dd>{measurement(observation.pulse,'bpm')}</dd></div><div><dt>Pernapasan</dt><dd>{measurement(observation.respiratoryRate,'/menit')}</dd></div><div><dt>Saturasi</dt><dd>{measurement(observation.spo2,'%')}</dd></div></dl></article>{:else}<p class="empty">Belum ada observasi keperawatan.</p>{/each}</div>
</section>
<style>
.crumb{font-size:12px;color:#747b8c;margin:0 0 14px}.record-panel{margin-bottom:14px}.clinical-grid{display:grid;grid-template-columns:repeat(2,minmax(200px,1fr));gap:16px;margin:18px 0}.clinical-grid div{padding:12px;background:#f8f9fb;border:1px solid #e5e7eb;border-radius:8px}.clinical-grid dt,.values dt{color:#737a8a;font-size:11px}.clinical-grid dd,.values dd{margin:5px 0 0;font-size:14px;white-space:pre-wrap}.observe-form{margin:12px 0}.observe-form summary{display:inline-block;cursor:pointer}.observe-form[open] summary{margin-bottom:14px}.vitals-grid{display:grid;grid-template-columns:repeat(3,minmax(100px,1fr));gap:10px}.values{margin:10px 0}.observation{border-top:1px solid #e5e7eb;padding:14px 0}.observation p{font-size:13px;margin:7px 0}.observation-heading{display:flex;justify-content:space-between}.values div{padding:8px;background:#f8f9fb;border-radius:6px}@media(max-width:650px){.clinical-grid{grid-template-columns:1fr}.vitals-grid{grid-template-columns:repeat(2,minmax(110px,1fr))}}
</style>
